import React,{useEffect,useMemo,useState} from 'react';
import{createRoot}from'react-dom/client';
import{parseCSV,analyzeRows,packetFor,ENGINE_VERSION}from'./engine';
import{BIG_MOVE_UNIVERSE,DEFAULT_BIG_MOVE_SYMBOLS,buildBigMoveCandidates,bigMovePacket}from'./bigmove';
import{buildIntradayReport,reportPacket}from'./report';
import'./styles.css';

const money=v=>v>=1e9?`$${(v/1e9).toFixed(1)}B`:v>=1e6?`$${(v/1e6).toFixed(1)}M`:v>=1e3?`$${(v/1e3).toFixed(0)}K`:`$${Math.round(v||0)}`;
const signed=n=>`${n>0?'+':''}${n}`;
const dirEl=b=><span className={`bias ${(b||'unknown').toLowerCase()}`}>{b==='BULLISH'?'▲':b==='BEARISH'?'▼':'◆'} {b||'UNKNOWN'}</span>;
const qualityClass=n=>n>=70?'high':n>=50?'medium':'low';
const readWatch=()=>{try{return JSON.parse(localStorage.getItem('smartflow-watchlist')||'[]')}catch{return[]}};
const readBigMoveHistory=()=>{try{return JSON.parse(localStorage.getItem('smartflow-bigmove-history')||'[]')}catch{return[]}};
async function readApiJson(r){const text=await r.text();try{return text?JSON.parse(text):{};}catch{const isHtml=/^\s*</.test(text);throw new Error(isHtml?`Server returned HTML instead of JSON (HTTP ${r.status}). Check the Railway deployment/logs.`:`Invalid server response (HTTP ${r.status}): ${text.slice(0,160)}`);}}
function routeFromUrl(){const q=new URLSearchParams(location.search);return{view:q.get('view')||'dashboard',ticker:(q.get('ticker')||'').toUpperCase()};}
function tagBatch(rows,kind,filename){const forced=kind==='stocks'?'STOCK':kind==='etfs'?'ETF':null;const tagged=rows.map(r=>({...r,_forcedAssetType:forced,_batchKind:kind,_batchFile:filename,_rowId:`${kind}:${filename}:${r._row}`}));tagged._meta=rows._meta;return tagged;}
function mergeBatches(datasets){const active=Object.values(datasets).filter(Boolean);if(!active.length)return null;const merged=[];const headers=[];for(const b of active){for(const h of b.rows._meta?.headers||[])if(!headers.includes(h))headers.push(h);merged.push(...b.rows);}merged._meta={headers,source:'Barchart multi-batch CSV',inputLines:merged.length,batches:active.map(b=>({kind:b.kind,filename:b.filename,rows:b.rows.length,forcedAssetType:b.kind==='stocks'?'STOCK':b.kind==='etfs'?'ETF':'AUTO'}))};return merged;}

const copy={
 en:{dashboard:'Dashboard',flow:'Flow Intelligence',report:'📊 Intraday Report',stocks:'Stocks',etfs:'ETFs',bigmove:'🚀 Big Move',watch:'Watchlist',audit:'Data Audit',upload:'Upload Barchart Options Flow CSV',simple:'Simple',advanced:'Advanced',signals:'🎯 Signals',plan:'▣ Trade Plan',risk:'⚠ Risk',refresh:'Refresh price',analyze:'Analyze with AI',why:'Why this matters',coverage:'Coverage',conf:'Confidence',score:'Smart Money Score',legacy:'Legacy benchmark',back:'Back',highConv:'High conviction',reset:'Reset filters',all:'All',noData:'No CSV loaded yet.'},
 el:{dashboard:'Dashboard',flow:'Flow Intelligence',report:'📊 Intraday Report',stocks:'Μετοχές',etfs:'ETFs',bigmove:'🚀 Big Move',watch:'Watchlist',audit:'Έλεγχος Δεδομένων',upload:'Ανέβασε Barchart Options Flow CSV',simple:'Απλό',advanced:'Προχωρημένο',signals:'🎯 Σήματα',plan:'▣ Πλάνο',risk:'⚠ Ρίσκο',refresh:'Ανανέωση τιμής',analyze:'Ανάλυση με AI',why:'Γιατί έχει σημασία',coverage:'Κάλυψη',conf:'Βεβαιότητα',score:'Smart Money Score',legacy:'Legacy benchmark',back:'Πίσω',highConv:'Υψηλή βεβαιότητα',reset:'Καθαρισμός φίλτρων',all:'Όλα',noData:'Δεν έχει φορτωθεί CSV.'}
};

function App(){
 const[lang,setLang]=useState('el'),[mode,setMode]=useState('simple'),[analysis,setAnalysis]=useState(null),[datasets,setDatasets]=useState({stocks:null,etfs:null,auto:null}),[quote,setQuote]=useState({}),[ai,setAi]=useState({}),[reportAI,setReportAI]=useState(null),[reportLoading,setReportLoading]=useState(false),[tab,setTab]=useState('signals'),[status,setStatus]=useState(''),[route,setRoute]=useState(routeFromUrl),[watchlist,setWatchlist]=useState(readWatch),[bigMoveRaw,setBigMoveRaw]=useState(null),[bigMoveHistory,setBigMoveHistory]=useState(readBigMoveHistory),[bigMoveAI,setBigMoveAI]=useState(null),[bigMoveLoading,setBigMoveLoading]=useState(false),[naturalGas,setNaturalGas]=useState(null),[naturalGasLoading,setNaturalGasLoading]=useState(false);
 const t=copy[lang];
 useEffect(()=>{const fn=()=>setRoute(routeFromUrl());addEventListener('popstate',fn);return()=>removeEventListener('popstate',fn)},[]);
 useEffect(()=>{localStorage.setItem('smartflow-watchlist',JSON.stringify(watchlist))},[watchlist]);
 useEffect(()=>{localStorage.setItem('smartflow-bigmove-history',JSON.stringify(bigMoveHistory.slice(0,20)))},[bigMoveHistory]);
 function go(view,ticker=''){const q=new URLSearchParams();q.set('view',view);if(ticker)q.set('ticker',ticker);history.pushState({},'',`${location.pathname}?${q}`);setRoute({view,ticker});if(view==='ticker')setTab('signals');window.scrollTo({top:0,behavior:'smooth'});}
 const current=useMemo(()=>analysis?.tickers.find(x=>x.symbol===route.ticker)||null,[analysis,route.ticker]);
 const previousBigSnapshot=useMemo(()=>{if(!bigMoveHistory.length)return null;return bigMoveRaw?.generatedAt&&bigMoveHistory[0]?.sourceAt===bigMoveRaw.generatedAt?bigMoveHistory[1]||null:bigMoveHistory[0];},[bigMoveHistory,bigMoveRaw]);
 const bigMoveCandidates=useMemo(()=>buildBigMoveCandidates(bigMoveRaw?.rows||[],analysis,previousBigSnapshot),[bigMoveRaw,analysis,previousBigSnapshot]);
 const intradayReport=useMemo(()=>buildIntradayReport(analysis,quote),[analysis,quote]);
 async function load(e,kind){const f=e.target.files?.[0];if(!f)return;try{setStatus('Processing…');const parsed=parseCSV(await f.text()),rows=tagBatch(parsed,kind,f.name),next={...datasets,[kind]:{kind,filename:f.name,rows}};setDatasets(next);const merged=mergeBatches(next),a=merged?analyzeRows(merged):null;setAnalysis(a);setStatus(a?`${a.rawRows} rows · ${a.tickers.length} tickers · ${a.dataAudit.assetClassification.STOCK} stocks · ${a.dataAudit.assetClassification.ETF} ETFs · ${a.dataAudit.assetClassification.UNKNOWN} unverified · ${ENGINE_VERSION}`:'No dataset loaded.');setAi({});setReportAI(null);go(kind==='stocks'?'stocks':kind==='etfs'?'etfs':'dashboard');}catch(err){setStatus('Error: '+err.message)}e.target.value='';}
 function clearBatch(kind){const next={...datasets,[kind]:null};setDatasets(next);const merged=mergeBatches(next),a=merged?analyzeRows(merged):null;setAnalysis(a);setAi({});setReportAI(null);setStatus(a?`${a.rawRows} rows · ${a.tickers.length} tickers · ${a.dataAudit.assetClassification.STOCK} stocks · ${a.dataAudit.assetClassification.ETF} ETFs · ${a.dataAudit.assetClassification.UNKNOWN} unverified · ${ENGINE_VERSION}`:'No dataset loaded.');}
 async function refresh(s=current){if(!s)return;setStatus('Refreshing price…');try{const r=await fetch(`/api/quote/${s.symbol}`),d=await readApiJson(r);if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);setQuote(q=>({...q,[s.symbol]:d}));setStatus(`${s.symbol} price refreshed.`);}catch(e){setStatus('Price: '+e.message)}}
 async function refreshReportContext(){if(!analysis)return;const ranked=[...analysis.tickers].sort((a,b)=>b.signalQuality-a.signalQuality);const preferred=['SPY','QQQ','IWM','DIA','SMH','SOXX','SOXL','SOXS','TQQQ','SQQQ'];const selected=[];for(const sym of preferred){if(ranked.some(x=>x.symbol===sym)&&!selected.includes(sym))selected.push(sym);}for(const s of ranked){if(selected.length>=8)break;if(!selected.includes(s.symbol))selected.push(s.symbol);}if(!selected.length)return;setReportLoading(true);setStatus(`Refreshing ${selected.length} price contexts…`);try{const r=await fetch('/api/quotes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({symbols:selected})}),d=await readApiJson(r);if(!r.ok)throw new Error(d.error||d.errors?.join(' · ')||`HTTP ${r.status}`);setQuote(q=>({...q,...Object.fromEntries((d.rows||[]).map(x=>[x.symbol,x]))}));setReportAI(null);setStatus(`Intraday context: ${d.rows?.length||0} quotes refreshed${d.errors?.length?` · ${d.errors.length} errors`:''}.`);}catch(e){setStatus('Intraday context: '+e.message);}finally{setReportLoading(false)}}
 async function runReportAI(force=false){if(!intradayReport?.topSignal)return;const top=intradayReport.topSignal;if(!force&&(top.confidence<40||top.coverage<30||Math.abs(top.score)<20)){setReportAI({skipped:true,reason:`Top signal ${top.symbol}: confidence ${top.confidence}% · coverage ${top.coverage}% · |score| ${Math.abs(top.score)}.`});return;}setReportAI({loading:true});try{const r=await fetch('/api/ai/intraday-report',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({packet:reportPacket(intradayReport),force})}),d=await readApiJson(r);if(!r.ok)throw new Error((d.errors?.length?d.errors:[d.error||`HTTP ${r.status}`]).join(' · '));setReportAI({...d,loading:false});}catch(e){setReportAI({loading:false,error:e.message});}}
 async function scanBigMove(symbols){setBigMoveLoading(true);setBigMoveAI(null);setStatus('Big Move: loading split-adjusted daily history…');try{const r=await fetch('/api/big-move/scan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({symbols})}),d=await readApiJson(r);if(!r.ok)throw new Error(d.error||d.errors?.join(' · ')||`HTTP ${r.status}`);const prev=bigMoveHistory[0]||null,candidates=buildBigMoveCandidates(d.rows||[],analysis,prev);setBigMoveRaw(d);const snap={at:new Date().toISOString(),sourceAt:d.generatedAt,rows:candidates.map(x=>({symbol:x.symbol,close:x.close,setupScore:x.setupScore,locationScore:x.locationScore,reversalScore:x.reversalScore,status:x.status}))};setBigMoveHistory(h=>[snap,...h.filter(x=>x.sourceAt!==d.generatedAt)].slice(0,20));setStatus(`Big Move: ${d.rows?.length||0} ETFs refreshed${d.errors?.length?` · ${d.errors.length} errors`:''}.`);}catch(e){setStatus('Big Move: '+e.message);}finally{setBigMoveLoading(false)}}
 async function refreshNaturalGas(){setNaturalGasLoading(true);setStatus('Natural Gas: refreshing macro context…');try{const r=await fetch('/api/macro/natural-gas'),d=await readApiJson(r);if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);setNaturalGas(d);setBigMoveAI(null);setStatus(`Natural Gas: ${d.symbol} refreshed · ${d.regime}.`);}catch(e){setStatus('Natural Gas: '+e.message);}finally{setNaturalGasLoading(false)}}
 async function runBigMoveAI(force=false){if(!bigMoveCandidates.length)return;setBigMoveAI({loading:true});try{const r=await fetch('/api/ai/big-move',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({packet:bigMovePacket(bigMoveCandidates,naturalGas),force})}),d=await readApiJson(r);if(!r.ok)throw new Error((d.errors?.length?d.errors:[d.error||`HTTP ${r.status}`]).join(' · '));setBigMoveAI({...d,loading:false});}catch(e){setBigMoveAI({loading:false,error:e.message});}}
 async function runAI(s=current,force=false){if(!s)return;if(!s.aiRecommended&&!force){setAi(x=>({...x,[s.symbol]:{loading:false,skipped:true,reason:`Confidence ${s.confidence}% · coverage ${s.coverage}% · |score| ${Math.abs(s.score)}. AI was not called to avoid spending on a weak signal.`}}));return;}setAi(x=>({...x,[s.symbol]:{loading:true}}));try{const r=await fetch('/api/ai/analyze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({packet:packetFor(s,quote[s.symbol])})}),d=await readApiJson(r);if(!r.ok)throw new Error((d.errors?.length?d.errors:[d.error||`HTTP ${r.status}`]).join(' · '));setAi(x=>({...x,[s.symbol]:{...d,loading:false}}));}catch(e){setAi(x=>({...x,[s.symbol]:{loading:false,error:e.message}}));}}
 function toggleWatch(symbol){setWatchlist(w=>w.includes(symbol)?w.filter(x=>x!==symbol):[...w,symbol]);}
 const aiNow=current?ai[current.symbol]:null;
 return <div className="app">
   <Header lang={lang}setLang={setLang}mode={mode}setMode={setMode}t={t}/>
   <Nav route={route}go={go}t={t}watchCount={watchlist.length}/>
   <UploadBar t={t}lang={lang}load={load}clearBatch={clearBatch}status={status}datasets={datasets}/>
   <div className="pageShell">
     {route.view==='dashboard'&&<Dashboard analysis={analysis}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}/>} 
     {route.view==='report'&&<IntradayReportPage report={intradayReport} lang={lang} ai={reportAI} loading={reportLoading} refreshContext={refreshReportContext} runAI={runReportAI} go={go}/>}
     {route.view==='flow'&&<ExplorerPage analysis={analysis}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}fixedAsset={null}/>}
     {route.view==='stocks'&&<ExplorerPage analysis={analysis}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}fixedAsset="STOCK"/>}
     {route.view==='etfs'&&<ExplorerPage analysis={analysis}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}fixedAsset="ETF"/>}
     {route.view==='bigmove'&&<BigMovePage lang={lang}analysis={analysis}candidates={bigMoveCandidates}raw={bigMoveRaw}history={bigMoveHistory}loading={bigMoveLoading}scan={scanBigMove}ai={bigMoveAI}runAI={runBigMoveAI}naturalGas={naturalGas}naturalGasLoading={naturalGasLoading}refreshNaturalGas={refreshNaturalGas}/>}
     {route.view==='watch'&&<WatchlistPage analysis={analysis}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}/>} 
     {route.view==='audit'&&<DataAudit analysis={analysis}lang={lang}/>} 
     {route.view==='ticker'&&<TickerPage s={current}analysis={analysis}lang={lang}mode={mode}t={t}tab={tab}setTab={setTab}quote={current?quote[current.symbol]:null}ai={aiNow}refresh={refresh}runAI={runAI}go={go}watched={current?watchlist.includes(current.symbol):false}toggleWatch={toggleWatch}/>} 
   </div>
   <footer>Educational decision-support beta · Not personalized investment advice. Options flow can represent hedging/closing activity. Leveraged ETFs reset daily, have path dependency and can lose capital very quickly.</footer>
 </div>;
}

function Header({lang,setLang,mode,setMode,t}){return <header><div><div className="brand">SMART FLOW <small>PRIVATE BETA</small></div><div className="sub">Barchart options-flow intelligence · Twelve Data context · deterministic engine + dual AI review</div></div><div className="switch"><button className={lang==='el'?'on':''}onClick={()=>setLang('el')}>ΕΛ</button><button className={lang==='en'?'on':''}onClick={()=>setLang('en')}>EN</button><span className="switchSep"/><button className={mode==='simple'?'on':''}onClick={()=>setMode('simple')}>{t.simple}</button><button className={mode==='advanced'?'on':''}onClick={()=>setMode('advanced')}>{t.advanced}</button></div></header>}
function Nav({route,go,t,watchCount}){const items=[['dashboard',t.dashboard],['flow',t.flow],['report',t.report],['stocks',t.stocks],['etfs',t.etfs],['bigmove',t.bigmove],['watch',`${t.watch} ${watchCount?`(${watchCount})`:''}`],['audit',t.audit]];return <nav className="topnav">{items.map(([k,l])=><button key={k}className={route.view===k?'active':''}onClick={()=>go(k)}>{l}</button>)}</nav>}
function UploadBar({lang,load,clearBatch,status,datasets}){const gr=lang==='el';const cards=[['stocks',gr?'Μετοχές / Stocks CSV':'Stocks CSV',gr?'Όλες οι γραμμές αυτού του αρχείου ταξινομούνται ως STOCK.':'Every row in this file is classified as STOCK.'],['etfs','ETFs CSV',gr?'Όλες οι γραμμές αυτού του αρχείου ταξινομούνται ως ETF.':'Every row in this file is classified as ETF.'],['auto',gr?'Mixed / Auto CSV':'Mixed / Auto CSV',gr?'Προαιρετικό. Χρησιμοποιεί Asset Type του CSV ή το ETF registry. Άγνωστα tickers μένουν UNKNOWN — όχι STOCK από default.':'Optional. Uses the CSV Asset Type field or ETF registry. Unknown tickers stay UNKNOWN — never default STOCK.']];return <section className="uploadDeck"><div className="uploadDeckHead"><div><b>{gr?'Barchart Options Flow uploads':'Barchart Options Flow uploads'}</b><span>{gr?'Φόρτωσε Stocks και ETFs ξεχωριστά. Τα datasets ενώνονται μόνο για cross-confirmation, αλλά κρατούν τον asset type του upload.':'Load Stocks and ETFs separately. Datasets are merged only for cross-confirmation while preserving the upload asset type.'}</span></div><small>{status||'No file loaded.'}</small></div><div className="uploadCards">{cards.map(([kind,title,help])=>{const d=datasets[kind];return <div className={`uploadCard ${d?'loaded':''}`} key={kind}><div className="uploadCardTitle"><strong>{title}</strong>{d&&<button onClick={()=>clearBatch(kind)}>×</button>}</div><p>{help}</p><label>{d?(gr?'Αντικατάσταση CSV':'Replace CSV'):(gr?'Επιλογή CSV':'Choose CSV')}<input type="file" accept=".csv,text/csv" onChange={e=>load(e,kind)}/></label>{d&&<div className="batchMeta"><b title={d.filename}>{d.filename}</b><span>{d.rows.length} rows</span></div>}</div>})}</div></section>}

function Dashboard({analysis,lang,go,watchlist,toggleWatch}){const gr=lang==='el';if(!analysis)return <Empty lang={lang}/>;const etfs=analysis.tickers.filter(x=>x.asset.type==='ETF'),stocks=analysis.tickers.filter(x=>x.asset.type==='STOCK'),unknown=analysis.tickers.filter(x=>x.asset.type==='UNKNOWN'),ready=analysis.tickers.filter(x=>x.aiRecommended),top=[...analysis.tickers].sort((a,b)=>b.signalQuality-a.signalQuality).slice(0,8);return <>
 <div className="pageTitle"><div><h1>{gr?'Κέντρο σημάτων':'Signal dashboard'}</h1><p>{gr?'Πρώτα βλέπεις τα καλύτερα deterministic signals. Το AI καλείται μόνο όταν το ζητήσεις.':'Start with the strongest deterministic signals. AI is only called when you request it.'}</p></div><button onClick={()=>go('audit')} className="secondary">{gr?'Έλεγχος CSV →':'CSV audit →'}</button></div>
 <div className="summaryGrid"><Metric k={gr?'Tickers':'Tickers'}v={analysis.tickers.length}/><Metric k="ETFs"v={etfs.length}/><Metric k={gr?'Μετοχές':'Stocks'}v={stocks.length}/><Metric k={gr?'Άγνωστος τύπος':'Unknown asset'}v={unknown.length}/><Metric k={gr?'AI-ready signals':'AI-ready signals'}v={ready.length}/><Metric k={gr?'Multi-leg groups':'Multi-leg groups'}v={analysis.multiLegGroups}/></div>{unknown.length>0&&<div className="warning">{gr?'Τα UNKNOWN tickers δεν εμφανίζονται ούτε στις Μετοχές ούτε στα ETFs μέχρι να επιβεβαιωθεί ο τύπος τους. Φόρτωσέ τα από το σωστό ξεχωριστό CSV ή έλεγξε το Data Audit.':'UNKNOWN tickers are excluded from both Stocks and ETFs until their type is verified. Load them through the correct dedicated CSV or inspect Data Audit.'}</div>}
 <section className="logicCard"><h3>{gr?'Πώς διαβάζουμε τα 3 βασικά metrics':'How to read the 3 core metrics'}</h3><div className="logicGrid"><div><b>Score</b><p>{gr?'Κατεύθυνση και ισχύς του flow από -100 έως +100. Αρνητικό = bearish, θετικό = bullish.':'Direction and strength from -100 to +100. Negative = bearish, positive = bullish.'}</p></div><div><b>Confidence</b><p>{gr?'Ποιότητα των evidence: execution side, opening/closing, συγκέντρωση και ambiguity. Δεν είναι πιθανότητα κέρδους.':'Evidence quality: execution side, opening/closing, concentration and ambiguity. It is not probability of profit.'}</p></div><div><b>Coverage</b><p>{gr?'Πόσο από το premium μπορεί να ταξινομηθεί directional. Χαμηλή κάλυψη = το engine βλέπει μεγάλο μέρος ως ασαφές.':'How much premium can be directionally classified. Low coverage means a large share remains ambiguous.'}</p></div></div></section>
 <section className="section"><div className="sectionHead"><div><h2>{gr?'Καλύτερα signals τώρα':'Best signals now'}</h2><span>{gr?'Ταξινόμηση με Signal Quality = confidence + coverage + |score|.':'Ranked by Signal Quality = confidence + coverage + |score|.'}</span></div><button onClick={()=>go('flow')}>{gr?'Όλα τα signals →':'All signals →'}</button></div><SignalTable rows={top}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}/></section>
 </>}

function ExplorerPage({analysis,lang,go,watchlist,toggleWatch,fixedAsset}){const gr=lang==='el';return <><div className="pageTitle"><div><h1>{fixedAsset==='STOCK'?(gr?'Μετοχές':'Stocks'):fixedAsset==='ETF'?'ETFs':(gr?'Flow Intelligence':'Flow Intelligence')}</h1><p>{gr?'Φίλτρα για να μην χάνεται το σημαντικό signal μέσα στον θόρυβο.':'Use filters so the strongest signals do not disappear in the noise.'}</p></div></div>{!analysis?<Empty lang={lang}/>:<SignalExplorer rows={analysis.tickers}fixedAsset={fixedAsset}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}/>}</>}

function SignalExplorer({rows,fixedAsset,lang,go,watchlist,toggleWatch}){const gr=lang==='el';const[asset,setAsset]=useState(fixedAsset||'ALL'),[bias,setBias]=useState('ALL'),[minConf,setMinConf]=useState(0),[minCov,setMinCov]=useState(0),[minScore,setMinScore]=useState(0),[sort,setSort]=useState('quality');useEffect(()=>setAsset(fixedAsset||'ALL'),[fixedAsset]);const filtered=useMemo(()=>{let x=rows.filter(s=>(asset==='ALL'||s.asset.type===asset)&&(bias==='ALL'||s.bias===bias)&&s.confidence>=minConf&&s.coverage>=minCov&&Math.abs(s.score)>=minScore);return [...x].sort((a,b)=>sort==='confidence'?b.confidence-a.confidence:sort==='coverage'?b.coverage-a.coverage:sort==='score'?Math.abs(b.score)-Math.abs(a.score):sort==='premium'?b.eligiblePremium-a.eligiblePremium:b.signalQuality-a.signalQuality)},[rows,asset,bias,minConf,minCov,minScore,sort]);function preset(){setMinConf(60);setMinCov(50);setMinScore(30);setBias('ALL')}function reset(){setMinConf(0);setMinCov(0);setMinScore(0);setBias('ALL');if(!fixedAsset)setAsset('ALL');setSort('quality')}return <section className="section"><div className="filters">{!fixedAsset&&<label>{gr?'Τύπος':'Asset'}<select value={asset}onChange={e=>setAsset(e.target.value)}><option value="ALL">{gr?'Όλα':'All'}</option><option value="STOCK">{gr?'Μετοχές':'Stocks'}</option><option value="ETF">ETF</option><option value="UNKNOWN">{gr?'Άγνωστο / μη επιβεβαιωμένο':'Unknown / unverified'}</option></select></label>}<label>Bias<select value={bias}onChange={e=>setBias(e.target.value)}><option value="ALL">{gr?'Όλα':'All'}</option><option>BULLISH</option><option>BEARISH</option><option>MIXED</option></select></label><label>{gr?'Min βεβαιότητα':'Min confidence'}<select value={minConf}onChange={e=>setMinConf(+e.target.value)}>{[0,40,50,60,70,80].map(x=><option key={x}value={x}>{x}%</option>)}</select></label><label>{gr?'Min κάλυψη':'Min coverage'}<select value={minCov}onChange={e=>setMinCov(+e.target.value)}>{[0,30,40,50,60,70,80].map(x=><option key={x}value={x}>{x}%</option>)}</select></label><label>Min |score|<select value={minScore}onChange={e=>setMinScore(+e.target.value)}>{[0,20,30,40,50,60].map(x=><option key={x}value={x}>{x}</option>)}</select></label><label>{gr?'Ταξινόμηση':'Sort'}<select value={sort}onChange={e=>setSort(e.target.value)}><option value="quality">Signal Quality</option><option value="confidence">Confidence</option><option value="coverage">Coverage</option><option value="score">|Score|</option><option value="premium">Premium</option></select></label><div className="filterActions"><button className="accent"onClick={preset}>{gr?'Υψηλή βεβαιότητα':'High conviction'}</button><button onClick={reset}>{gr?'Reset':'Reset'}</button></div></div><div className="resultMeta">{filtered.length} / {rows.length} {gr?'signals εμφανίζονται':'signals shown'}</div>{filtered.length?<SignalTable rows={filtered}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}/>:<div className="noResults">{gr?'Κανένα signal δεν περνά τα φίλτρα. Χαμήλωσε τα thresholds.':'No signal passes the filters. Lower the thresholds.'}</div>}</section>}

function SignalTable({rows,lang,go,watchlist,toggleWatch}){const gr=lang==='el';return <div className="signalTable"><div className="signalHead"><span></span><span>Ticker</span><span>Bias</span><span>Score</span><span>{gr?'Βεβαιότητα':'Confidence'}</span><span>{gr?'Κάλυψη':'Coverage'}</span><span>Quality</span><span>{gr?'Premium':'Premium'}</span><span>AI</span></div>{rows.map(s=><div className="signalRow"key={s.symbol}onClick={()=>go('ticker',s.symbol)}><button className={`star ${watchlist.includes(s.symbol)?'on':''}`}onClick={e=>{e.stopPropagation();toggleWatch(s.symbol)}}>{watchlist.includes(s.symbol)?'★':'☆'}</button><span className="tickerCell"><b>{s.symbol}</b><small>{s.asset.type} · {s.asset.sector} · {s.asset.classificationSource||'—'}</small></span><span>{dirEl(s.bias)}</span><strong className={s.score>0?'up':s.score<0?'down':''}>{signed(s.score)}</strong><span>{s.confidence}%</span><span>{s.coverage}%</span><span><i className={`quality ${qualityClass(s.signalQuality)}`}>{s.signalQuality}</i></span><span>{money(s.eligiblePremium)}</span><span className={s.aiRecommended?'ready':'muted'}>{s.aiRecommended?'READY':'OPTIONAL'}</span></div>)}</div>}

function WatchlistPage({analysis,lang,go,watchlist,toggleWatch}){const gr=lang==='el';const[input,setInput]=useState('');const matched=watchlist.map(sym=>analysis?.tickers.find(s=>s.symbol===sym)||{symbol:sym,missing:true});function add(){const s=input.toUpperCase().replace(/[^A-Z0-9.\-]/g,'');if(s&&!watchlist.includes(s))toggleWatch(s);setInput('')}return <><div className="pageTitle"><div><h1>Watchlist</h1><p>{gr?'Αποθηκεύεται τοπικά στον browser για το private beta.':'Stored locally in this browser for the private beta.'}</p></div><div className="watchAdd"><input value={input}onChange={e=>setInput(e.target.value)}onKeyDown={e=>e.key==='Enter'&&add()}placeholder="NVDA, QQQ…"/><button onClick={add}>+ Add</button></div></div><section className="section">{!watchlist.length?<div className="noResults">{gr?'Δεν έχεις προσθέσει ticker στο watchlist. Πάτησε ☆ σε ένα signal.':'Your watchlist is empty. Click ☆ on a signal.'}</div>:matched.map(s=>s.missing?<div className="watchMissing"key={s.symbol}><b>{s.symbol}</b><span>{gr?'Δεν υπάρχει στο τρέχον CSV.':'Not present in the current CSV.'}</span><button onClick={()=>toggleWatch(s.symbol)}>Remove</button></div>:<SignalTable key={s.symbol}rows={[s]}lang={lang}go={go}watchlist={watchlist}toggleWatch={toggleWatch}/>)}</section></>}


function BigMovePage({lang,analysis,candidates,raw,history,loading,scan,ai,runAI,naturalGas,naturalGasLoading,refreshNaturalGas}){
 const gr=lang==='el',limit=raw?.scanLimit||8;
 const[selected,setSelected]=useState(DEFAULT_BIG_MOVE_SYMBOLS);
 const[minSetup,setMinSetup]=useState(0);
 const visible=candidates.filter(x=>x.setupScore>=minSetup);
 const top=visible[0]||null;
 const examples=[
  ['SOXL','50x','$6 → $302','2024→2026','AI chip supercycle'],['Crude Oil 10x','155x','$9 → $140','2020→2022','Post-COVID demand'],['NAIL','52x','$2.1 → $110','2020→2022','Housing boom'],['TQQQ','5.3x','$17 → $91','2022→2024','AI rally'],['LABU','452x','$0.84 → $380','2020→2022','Biotech/mRNA wave']
 ];
 function toggle(sym){setSelected(x=>x.includes(sym)?x.filter(s=>s!==sym):x.length>=limit?x:[...x,sym]);}
 return <>
  <div className="pageTitle"><div><h1>🚀 BIG MOVE DETECTOR</h1><p>{gr?'Research scanner για leveraged ETFs που βρίσκονται σε βαθύ drawdown και αρχίζουν να δείχνουν πρώιμη αντιστροφή. Δεν ψάχνει «σίγουρο 50x»· ψάχνει setups που αξίζουν παρακολούθηση.':'Research scanner for leveraged ETFs in deep drawdowns that are beginning to show early reversal evidence. It does not predict a “sure 50x”; it identifies setups worth monitoring.'}</p></div><button className="secondary" disabled={loading||!selected.length} onClick={()=>scan(selected)}>{loading?(gr?'Σάρωση…':'Scanning…'):(gr?`↻ Ανανέωση ${selected.length} ETF`:`↻ Refresh ${selected.length} ETFs`)}</button></div>
  <div className="bigMoveWarning"><b>{gr?'Υψηλό ρίσκο:':'High risk:'}</b> {gr?'Τα leveraged ETFs κάνουν daily reset, έχουν path dependency/volatility drag και μπορούν να χάσουν μεγάλο μέρος της αξίας τους πολύ γρήγορα. «Κοντά στο low» δεν σημαίνει ότι είναι φθηνό ή ότι θα επιστρέψει στο παλιό high.':'Leveraged ETFs reset daily, have path dependency/volatility drag and can lose a large share of value very quickly. “Near the low” does not mean cheap or imply a return to a prior high.'}</div>
  <NaturalGasCard data={naturalGas} loading={naturalGasLoading} refresh={refreshNaturalGas} lang={lang}/>
  <section className="section"><div className="sectionHead"><div><h2>{gr?'Universe παρακολούθησης':'Monitoring universe'}</h2><span>{gr?`Twelve Data Basic protection: έως ${limit} symbols ανά manual scan. Το CSV Barchart είναι προαιρετικό αλλά προσθέτει flow confirmation.`:`Twelve Data Basic protection: up to ${limit} symbols per manual scan. Barchart CSV is optional but adds options-flow confirmation.`}</span></div><div className="filterActions"><button onClick={()=>setSelected(DEFAULT_BIG_MOVE_SYMBOLS.slice(0,limit))}>Core {limit}</button><button onClick={()=>setSelected([])}>{gr?'Καθαρισμός':'Clear'}</button></div></div><div className="universeGrid">{BIG_MOVE_UNIVERSE.map(x=><button key={x.symbol} className={selected.includes(x.symbol)?'selected':''} onClick={()=>toggle(x.symbol)} title={x.name}><b>{x.symbol}</b><span>{x.theme}</span></button>)}</div></section>
  <section className="section historicalExamples"><h2>{gr?'Ιστορικά archetypes — μόνο σαν ιδέα του scanner':'Historical archetypes — concept references only'}</h2><p>{gr?'Τα παρακάτω είναι τα παραδείγματα που έδωσες για το concept και δεν χρησιμοποιούνται στο scoring. Τα ονομαστικά historical prices/multiples μπορεί να παραμορφώνονται από splits ή reverse splits. Ο detector υπολογίζει τα δικά του metrics από daily split-adjusted ιστορικό Twelve Data.':'These are the examples supplied for the concept and are not used in scoring. Nominal historical prices/multiples can be distorted by splits or reverse splits. The detector computes its metrics from split-adjusted Twelve Data daily history.'}</p><div className="exampleGrid">{examples.map(([sym,mul,move,period,story])=><div key={sym}><b>{sym}</b><strong>{mul}</strong><span>{move}</span><small>{period} · {story}</small></div>)}</div></section>
  {!raw?<section className="empty bigEmpty"><b>{gr?'Πάτησε Ανανέωση για την πρώτη σάρωση.':'Press Refresh for the first scan.'}</b><p>{gr?'Η σάρωση χρησιμοποιεί μόνο manual API calls. Δεν υπάρχει background polling ώστε να προστατεύεται το free Twelve Data quota.':'The scan uses manual API calls only. There is no background polling, protecting the free Twelve Data quota.'}</p></section>:<>
   {raw.errors?.length>0&&<div className="auditWarnings"><h3>{gr?'Μερικά symbols απέτυχαν':'Some symbols failed'}</h3>{raw.errors.map((x,i)=><div key={i}>⚠ {x}</div>)}</div>}
   <div className="summaryGrid"><Metric k={gr?'Σαρώθηκαν':'Scanned'} v={candidates.length}/><Metric k={gr?'Watch / Reversal':'Watch / Reversal'} v={candidates.filter(x=>x.status!=='NO SETUP').length}/><Metric k={gr?'Καλύτερο setup':'Top setup'} v={top?`${top.symbol} ${top.setupScore}`:'—'}/><Metric k={gr?'Flow data':'Flow data'} v={analysis?`${candidates.filter(x=>x.flow.hasData).length}/${candidates.length}`:'0'}/><Metric k={gr?'Cache':'Cache'} v={`${raw.cacheMinutes||360}m`}/></div>
   <section className="section"><div className="sectionHead"><div><h2>{gr?'Κατάταξη Big Move':'Big Move ranking'}</h2><span>{gr?'Setup Score = 50% price location + 30% reversal evidence + 20% options-flow confirmation. Δεν είναι πιθανότητα κέρδους.':'Setup Score = 50% price location + 30% reversal evidence + 20% options-flow confirmation. It is not probability of profit.'}</span></div><label className="miniFilter">Min score <select value={minSetup} onChange={e=>setMinSetup(+e.target.value)}>{[0,50,55,60,65,70,75].map(x=><option key={x} value={x}>{x}</option>)}</select></label></div><BigMoveTable rows={visible} lang={lang}/></section>
   {top&&<section className="bigMoveTop"><div><span className={`setupStatus ${top.status.toLowerCase().replace(' ','-')}`}>{top.status}</span><h2>{top.symbol} · {top.theme}</h2><p>{gr?`Setup Score ${top.setupScore}. Βρίσκεται ${top.distanceHistoryLowPct}% πάνω από το ${top.fullHistoryLikely?'πιθανό ATL':'χαμηλό του διαθέσιμου history window'} και ${Math.abs(top.drawdownHistoryHighPct)}% κάτω από το ιστορικό high του window. Reversal score ${top.reversalScore}, flow confirmation ${top.flow.score}/100.`:`Setup Score ${top.setupScore}. It is ${top.distanceHistoryLowPct}% above the ${top.fullHistoryLikely?'likely ATL':'available history-window low'} and ${Math.abs(top.drawdownHistoryHighPct)}% below the history-window high. Reversal score ${top.reversalScore}, flow confirmation ${top.flow.score}/100.`}</p><small>{gr?'Macro condition που θα θέλαμε να δούμε:':'Macro condition we would want to see:'} {top.macro}</small></div><button className="aiBigBtn" disabled={ai?.loading} onClick={()=>runAI(false)}>{ai?.loading?'AI…':(gr?'🤖 AI: Βρες το επόμενο SOXL-style setup':'🤖 AI: Find the next SOXL-style setup')}</button></section>}
   {ai?.skipped&&<div className="aiSkip"><b>{gr?'Το AI δεν κλήθηκε':'AI was not called'}</b><p>{gr?'Το καλύτερο deterministic setup είναι ακόμη αδύναμο. Μπορείς να κάνεις force review μόνο για testing.':'The best deterministic setup is still weak. You can force a review for testing.'}</p><small>{ai.reason}</small><button onClick={()=>runAI(true)}>{gr?'Τρέξε AI ούτως ή άλλως':'Run AI anyway'}</button></div>}
   {ai?.error&&<div className="error">AI: {ai.error}</div>}
   {ai?.synthesis&&<BigMoveAI ai={ai} lang={lang}/>} 
   <BigMoveHistory history={history} lang={lang}/>
  </>}
 </>
}
function NaturalGasCard({data,loading,refresh,lang}){const gr=lang==='el';const pct=v=>v==null?'—':`${v>0?'+':''}${v.toFixed?.(1)??v}%`;return <section className="naturalGasCard"><div className="naturalGasHead"><div><span className="macroTag">🔥 NATURAL GAS</span><h3>{gr?'Macro δείκτης φυσικού αερίου':'Natural-gas macro indicator'}</h3><p>{gr?'Χρησιμοποιείται ως context στο Big Move AI και δεν αλλάζει το deterministic Setup Score.':'Used as context in Big Move AI and does not change the deterministic Setup Score.'}</p></div><button className="secondary" disabled={loading} onClick={refresh}>{loading?(gr?'Ανανέωση…':'Refreshing…'):(gr?'↻ Ανανέωση Natural Gas':'↻ Refresh Natural Gas')}</button></div>{data?<><div className="naturalGasMetrics"><Metric k={gr?'Πηγή':'Source'} v={data.proxy?'UNG proxy':(data.symbol||'Direct')}/><Metric k={gr?'Τιμή':'Price'} v={data.close!=null?`$${Number(data.close).toFixed(2)}`:'—'}/><Metric k="5D" v={pct(data.return5d)}/><Metric k="20D" v={pct(data.return20d)}/><Metric k="63D" v={pct(data.return63d)}/><Metric k={gr?'Καθεστώς':'Regime'} v={data.regime||'UNKNOWN'}/></div><div className={`gasRegime ${(data.regime||'unknown').toLowerCase()}`}><b>{data.regime||'UNKNOWN'}</b><span>{gr?(data.regime==='RISING'?'Η τάση του proxy/direct series είναι ανοδική.':data.regime==='FALLING'?'Η τάση του proxy/direct series είναι πτωτική.':'Η τάση είναι μικτή ή δεν υπάρχει αρκετή συμφωνία.'):(data.regime==='RISING'?'The proxy/direct series is trending higher.':data.regime==='FALLING'?'The proxy/direct series is trending lower.':'Trend is mixed or lacks enough agreement.')}</span></div>{data.warning&&<small className="gasWarning">⚠ {gr?'Σημείωση: ':'Note: '}{data.warning}</small>}</>:<p className="gasEmpty">{gr?'Πάτησε ανανέωση για να προσθέσεις το natural-gas context. Στο Twelve Data Basic/free χρησιμοποιούμε το UNG ως σαφώς επισημασμένο proxy όταν δεν υπάρχει direct commodity access.':'Press refresh to add natural-gas context. On Twelve Data Basic/free, UNG is used as a clearly labelled proxy when direct commodity market data is unavailable.'}</p>}</section>}

function BigMoveTable({rows,lang}){const gr=lang==='el';if(!rows.length)return <div className="noResults">{gr?'Κανένα setup δεν περνά το φίλτρο.':'No setup passes the filter.'}</div>;return <div className="bigMoveTable"><div className="bigMoveHead"><span>Ticker</span><span>Setup</span><span>Status</span><span>{gr?'Τιμή':'Price'}</span><span>{gr?'Από low':'From low'}</span><span>{gr?'Από high':'From high'}</span><span>Reversal</span><span>Flow</span><span>{gr?'Prior-high gap':'Prior-high gap'}</span><span>Δ score</span></div>{rows.map(x=><div className="bigMoveRow" key={x.symbol}><span className="tickerCell"><b>{x.symbol}</b><small>{x.theme}</small></span><strong>{x.setupScore}</strong><span><i className={`setupStatus ${x.status.toLowerCase().replace(' ','-')}`}>{x.status}</i></span><span>${x.close?.toFixed?.(2)}</span><span>{x.distanceHistoryLowPct?.toFixed?.(1)}%</span><span className="down">{x.drawdownHistoryHighPct?.toFixed?.(1)}%</span><span>{x.reversalScore}</span><span title={x.flow.hasData?`Direct/peer options flow present · directional ${x.flow.directional}`:'No options-flow confirmation in current CSV'}>{x.flow.score}{x.flow.hasData?' ✓':' ·'}</span><span title={gr?'Απόσταση από παλιό high — όχι price target':'Gap to prior high — not a price target'}>{x.priorHighMultiple?`${x.priorHighMultiple}x`:'—'}</span><span className={x.deltaScore>0?'up':x.deltaScore<0?'down':'muted'}>{x.deltaScore==null?'—':signed(x.deltaScore)}</span></div>)}</div>}
function BigMoveAI({ai,lang}){const gr=lang==='el',s=ai.synthesis,models=ai.meta;return <section className="panel bigMoveAI"><h3>{s.headline?.[lang]||(gr?'AI research synthesis':'AI research synthesis')}</h3><div className="bigAiHero"><b>{gr?'Κορυφαίο candidate':'Top candidate'}: {s.topCandidate||'—'}</b><p>{s.why?.[lang]||s.beginner?.[lang]||'—'}</p></div><div className="aiReview"><div><h4>{gr?'Τι το στηρίζει':'What supports it'}</h4><ul>{(s.supports?.[lang]||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div><div><h4>{gr?'Τι μπορεί να χαλάσει το setup':'What can break the setup'}</h4><ul>{(s.risks?.[lang]||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div></div><div className="bulletBox"><b>{gr?'Τι να παρακολουθούμε':'What to monitor'}</b><ul>{(s.monitor?.[lang]||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div>{ai.errors?.length>0&&<div className="warning"><b>{gr?'Μερική AI υποβάθμιση':'Partial AI fallback'}</b><div>{ai.errors.join(' · ')}</div></div>}{models&&<div className="qualityNote">Claude: {models.anthropic?.model||'—'} · effort {models.anthropic?.effort||'—'} · OpenAI: {models.openai?.model||'—'} · reasoning {models.openai?.reasoningEffort||'default'}</div>}<div className="warning">{gr?'Το AI δεν δημιουργεί target price ή «αναμενόμενο x». Η κατάταξη παραμένει deterministic και το AI μόνο εξηγεί/αμφισβητεί τα evidence.':'AI does not create a target price or an “expected multiple.” Ranking remains deterministic; AI only explains and challenges the evidence.'}</div></section>}
function BigMoveHistory({history,lang}){const gr=lang==='el';if(!history?.length)return null;return <section className="section"><h2>{gr?'Ιστορικό παρακολούθησης':'Monitoring history'}</h2><p>{gr?'Αποθηκεύεται τοπικά στον browser στο private beta. Μας επιτρέπει να βλέπουμε αν ένα setup βελτιώνεται ή χειροτερεύει από scan σε scan.':'Stored locally in the browser during private beta. This lets us see whether a setup improves or deteriorates from scan to scan.'}</p><div className="historyList">{history.slice(0,8).map((h,i)=>{const top=[...(h.rows||[])].sort((a,b)=>b.setupScore-a.setupScore)[0];return <div key={h.sourceAt||h.at||i}><span>{new Date(h.at).toLocaleString(lang==='el'?'el-GR':'en-US')}</span><b>{top?`${top.symbol} · ${top.setupScore} · ${top.status}`:'—'}</b><small>{h.rows?.length||0} ETFs</small></div>})}</div></section>}


function IntradayReportPage({report,lang,ai,loading,refreshContext,runAI,go}){
 const gr=lang==='el';if(!report)return <Empty lang={lang}/>;const top=report.topSignal,syn=ai?.synthesis;
 const topFact=top?`${top.symbol} · ${top.bias} · Score ${signed(top.score)} · ${gr?'βεβαιότητα':'confidence'} ${top.confidence}% · ${gr?'κάλυψη':'coverage'} ${top.coverage}%`:'';
 return <>
  <div className="pageTitle"><div><h1>📊 {gr?'OPTIONS FLOW — INTRADAY REPORT':'OPTIONS FLOW — INTRADAY REPORT'}</h1><p>{gr?'Dataset-level thesis όπως στο original, αλλά με διαχωρισμό Fact / Inference / Risk και χωρίς να μετατρέπει puts, MID executions ή strikes σε βεβαιότητες.':'Dataset-level thesis inspired by the original report, with Fact / Inference / Risk separated and no automatic leap from puts, MID executions or strikes to certainty.'}</p></div><div className="actions"><button onClick={refreshContext} disabled={loading}>{loading?(gr?'Ανανέωση…':'Refreshing…'):(gr?'↻ Ανανέωση market context':'↻ Refresh market context')}</button><button className="aiBtn" onClick={()=>runAI(false)} disabled={ai?.loading}>{ai?.loading?'AI…':(gr?'🤖 Ανάλυση report με AI':'🤖 Analyze report with AI')}</button></div></div>
  <section className="reportHero"><span>{gr?'🎯 1. TOP SIGNAL':'🎯 1. TOP SIGNAL'}</span><h2>{top?`${top.symbol} — ${top.bias}`:'—'}</h2><p><b>FACT:</b> {topFact}</p>{top&&<div className="reportMetrics"><Metric k="Put premium share" v={`${top.putPremiumShare}%`}/><Metric k="Directional bear share" v={`${top.bearishPremiumShareEligible}%`}/><Metric k="Confluence" v={top.confluence}/><Metric k={gr?'Price context':'Price context'} v={top.price.status==='READY'?`${signed(top.price.percentChange)}% · ${top.price.divergence}`:'PENDING'}/></div>}
   {top&&<p className="note"><b>{gr?'INFERENCE:':'INFERENCE:'}</b> {gr?`Το ${top.symbol} είναι το ισχυρότερο συνδυαστικό signal του τρέχοντος dataset με βάση signal quality, cross-confirmation και διαθέσιμο price context. Αυτό δεν σημαίνει πιθανότητα κέρδους ${top.confidence}%.`:`${top.symbol} is the strongest combined signal in the current dataset based on signal quality, cross-confirmation and available price context. This does not mean a ${top.confidence}% probability of profit.`}</p>}
  </section>
  <section className="section"><h2>⚡ 2. {gr?'DIVERGENCE ΑΝΙΧΝΕΥΣΗ':'DIVERGENCE DETECTION'}</h2><p>{gr?`Price coverage: ${report.priceCoverage.ready}/${report.priceCoverage.total}. Το divergence εμφανίζεται μόνο για tickers όπου έγινε Twelve Data refresh.`:`Price coverage: ${report.priceCoverage.ready}/${report.priceCoverage.total}. Divergence is shown only for tickers with refreshed Twelve Data price context.`}</p><div className="table"><table><thead><tr><th>Ticker</th><th>{gr?'Τιμή ημέρας':'Day move'}</th><th>Flow</th><th>Put share</th><th>{gr?'Directional bear':'Directional bear'}</th><th>Divergence</th><th>{gr?'Peers':'Peers'}</th></tr></thead><tbody>{[...report.divergences,...report.aligned].slice(0,14).map(x=><tr key={x.symbol}><td><button className="linkBtn" onClick={()=>go('ticker',x.symbol)}>{x.symbol}</button></td><td>{x.price.percentChange==null?'—':`${signed(x.price.percentChange)}%`}</td><td>{dirEl(x.bias)} {signed(x.score)}</td><td>{x.putPremiumShare}%</td><td>{x.bearishPremiumShareEligible}%</td><td><b className={x.price.divergence==='DIVERGENCE'?'down':'up'}>{x.price.divergence}</b></td><td>{x.confirms.length?`✓ ${x.confirms.join(', ')}`:x.conflicts.length?`⚠ ${x.conflicts.join(', ')}`:'—'}</td></tr>)}</tbody></table></div>{report.priceCoverage.ready===0&&<div className="warning">{gr?'Δεν υπάρχει ακόμη price divergence evidence. Πάτησε «Ανανέωση market context».':'No price-divergence evidence yet. Use “Refresh market context”.'}</div>}</section>
  <section className="section"><h2>🐋 3. {gr?'WHALE / LARGE PREMIUM ACTIVITY':'WHALE / LARGE PREMIUM ACTIVITY'}</h2><div className="table"><table><thead><tr><th>#</th><th>Ticker</th><th>Contract</th><th>Premium</th><th>Side</th><th>Position</th><th>Direction</th><th>Structure</th><th>Vol/OI</th></tr></thead><tbody>{report.topBlocks.slice(0,10).map((b,i)=><tr key={`${b.symbol}-${i}`}><td>{i+1}</td><td>{b.symbol}</td><td>{b.expiry||'?'} · {b.strike}{b.type?.[0]}</td><td>{money(b.premium)}</td><td>{b.side}</td><td>{b.positionEffect}</td><td>{b.direction}</td><td>{b.group?`${b.strategy} · ${b.group}`:'SINGLE'}</td><td>{b.volOi??'—'}</td></tr>)}</tbody></table></div><div className="warning">{gr?'Μεγάλο premium ≠ directional whale bet. Αν Position=UNKNOWN ή το trade είναι multi-leg, το report το παρουσιάζει ως evidence με caveat — όχι σαν βεβαιωμένη πρόθεση θεσμικού.':'Large premium ≠ confirmed directional whale bet. UNKNOWN position effect and multi-leg trades remain evidence with caveats, not certain institutional intent.'}</div></section>
  <section className="section"><h2>🧭 4. {gr?'CROSS-CONFIRMATION / MACRO CONTEXT':'CROSS-CONFIRMATION / MACRO CONTEXT'}</h2><div className="signalCards">{report.signals.slice(0,8).map(x=><div className="signalCard" key={x.symbol}><div><button className="linkBtn" onClick={()=>go('ticker',x.symbol)}><b>{x.symbol}</b></button><small>{x.assetType} · {x.sector}</small></div>{dirEl(x.bias)}<span>Score {signed(x.score)} · C {x.confidence}% · Cov {x.coverage}%</span><small>{x.confirms.length?`✓ ${x.confirms.join(', ')}`:x.conflicts.length?`⚠ ${x.conflicts.join(', ')}`:(gr?'χωρίς peer confirmation':'no peer confirmation')}</small></div>)}</div></section>
  <section className="section"><h2>⚠️ 5. {gr?'ΤΙ ΔΕΝ ΘΑ ΙΣΧΥΡΙΖΕΤΑΙ ΤΟ REPORT':'WHAT THE REPORT WILL NOT CLAIM'}</h2><ul><li>{gr?'100% puts δεν σημαίνει 100% bearish intent.':'100% puts does not mean 100% bearish intent.'}</li><li>{gr?'ASK/BID δεν αποδεικνύει BTO/STO.':'ASK/BID does not prove BTO/STO.'}</li><li>{gr?'MID execution δεν αποδεικνύει «methodical institution» ούτε αποκλείει hedge.':'MID execution does not prove “methodical institutional positioning” or rule out hedging.'}</li><li>{gr?'Sector ETF premium δεν μετατρέπεται μηχανικά σε 3x leveraged-ETF exposure.':'Sector ETF premium is not mechanically converted into 3x leveraged-ETF exposure.'}</li><li>{gr?'Option strike δεν γίνεται αυτόματα target/support/resistance.':'An option strike is not automatically a target/support/resistance level.'}</li></ul></section>
  <section className="section"><h2>📋 6. {gr?'MONITORING PLAN':'MONITORING PLAN'}</h2><div className="steps"><div><b>1</b>{gr?'Διάβασε πρώτα το Top Signal και τα conflicting peers.':'Read the Top Signal and conflicting peers first.'}</div><div><b>2</b>{gr?'Κάνε Twelve Data refresh ώστε να ελέγξεις αν η τιμή επιβεβαιώνει ή αποκλίνει από το flow.':'Refresh Twelve Data to see whether price confirms or diverges from flow.'}</div><div><b>3</b>{gr?'Έλεγξε τα μεγαλύτερα blocks για UNKNOWN position effect και probable spreads πριν θεωρήσεις το thesis θεσμικό bet.':'Inspect the largest blocks for UNKNOWN position effect and probable spreads before treating the thesis as an institutional bet.'}</div><div><b>4</b>{gr?'Το exact entry/stop/target θα προστεθεί μόνο όταν προκύπτει από πραγματικό price/technical context — όχι από AI εικασία.':'Exact entry/stop/target will be shown only when derived from real price/technical context — never AI guesswork.'}</div></div></section>
  {ai?.skipped&&<div className="aiSkip"><b>{gr?'Το dataset-level AI δεν κλήθηκε':'Dataset-level AI was not called'}</b><p>{ai.reason}</p><button onClick={()=>runAI(true)}>{gr?'Τρέξε AI ούτως ή άλλως':'Run AI anyway'}</button></div>}
  {ai?.error&&<div className="error">AI: {ai.error}</div>}
  {ai?.errors?.length>0&&<div className="warning">{ai.errors.join(' · ')}</div>}
  {syn&&<section className="panel reportAI"><h2>🤖 {gr?'AI SYNTHESIS — Analyst + Skeptic + Editor':'AI SYNTHESIS — Analyst + Skeptic + Editor'}</h2><EngineBadge meta={ai?.meta} lang={lang}/><h3>{syn.headline?.[lang]||`${syn.topSignal||top?.symbol||''}`}</h3><p>{syn.thesis?.[lang]||syn.why?.[lang]||'—'}</p><div className="aiReview"><div><h4>{gr?'Τι στηρίζει το thesis':'What supports the thesis'}</h4><ul>{(syn.supports?.[lang]||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div><div><h4>{gr?'Ισχυρότερος αντίλογος':'Strongest counter-case'}</h4><ul>{(syn.risks?.[lang]||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div></div><div className="bulletBox"><b>{gr?'Τι να παρακολουθήσεις':'What to monitor'}</b><ul>{(syn.monitor?.[lang]||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div>{syn.additionalPositions?.length>0&&<PositionIdeas items={syn.additionalPositions} lang={lang} go={go}/>}<div className="why"><b>{gr?'Για αρχάριους':'For beginners'}</b><p>{syn.beginner?.[lang]||'—'}</p></div></section>}
 </>;
}

function EngineBadge({meta,lang}){const gr=lang==='el';const a=meta?.anthropic,o=meta?.openai;return <div className="aiEngines">{gr?'🔗 2 AI μηχανές:':'🔗 2 AI engines:'} Claude ({a?.model||'—'}{a?.effort?` · ${a.effort}`:''}) {gr?'Αναλυτής':'Analyst'} → OpenAI ({o?.model||'—'}{o?.reasoningEffort?` · ${o.reasoningEffort}`:''}) {gr?'Σκεπτικιστής':'Skeptic'} → Claude {gr?'Συντάκτης':'Editor'}</div>}
function PositionIdeas({items,lang,go}){
 const gr=lang==='el';
 const etfs=items.filter(x=>x.assetType==='ETF'),stocks=items.filter(x=>x.assetType==='STOCK'),other=items.filter(x=>x.assetType!=='ETF'&&x.assetType!=='STOCK');
 const row=x=><div className="positionRow" key={x.symbol}><button className="linkBtn" onClick={()=>go('ticker',x.symbol)}><b>{x.symbol}</b></button>{dirEl(x.bias)}<span>Score {signed(x.score)} · C {x.confidence}% · Cov {x.coverage}%</span><p>{x.rationale?.[lang]||'—'}</p></div>;
 const group=(title,rows)=>rows.length>0&&<div className="positionGroup" key={title}><h4>{title} ({rows.length})</h4><div className="positionList">{rows.map(row)}</div></div>;
 return <div className="positionIdeas"><b>{gr?'Επιπλέον θέσεις ETF/Μετοχών προς παρακολούθηση':'Additional ETF/stock positions to watch'}</b>{group('ETFs',etfs)}{group(gr?'Μετοχές':'Stocks',stocks)}{group(gr?'Άλλο':'Other',other)}</div>;
}
function DataAudit({analysis,lang}){const gr=lang==='el';if(!analysis)return <Empty lang={lang}/>;const a=analysis.dataAudit;const labels={symbol:'Symbol',type:'Call/Put',side:'Bid/Ask side',strike:'Strike',expiry:'Expiry',dte:'DTE',premium:'Premium',oi:'Open interest',volume:'Volume',size:'Size',delta:'Delta',iv:'IV',price:'Trade price',bid:'Bid',ask:'Ask',time:'Timestamp',code:'BTO/STO field',tradeId:'Trade ID',assetType:'Asset type',condition:'Condition'};return <><div className="pageTitle"><div><h1>{gr?'Έλεγχος Barchart CSV':'Barchart CSV audit'}</h1><p>{gr?'Εδώ φαίνεται τι πραγματικά διάβασε ο parser. Αυτό είναι το πρώτο σημείο ελέγχου αν ένα score φαίνεται λάθος.':'This shows what the parser actually read. Check here first when a score looks wrong.'}</p></div></div><div className="summaryGrid"><Metric k={gr?'Input rows':'Input rows'}v={a.inputRows}/><Metric k={gr?'Canonical trades':'Canonical trades'}v={a.canonicalTrades}/><Metric k={gr?'ETFs':'ETFs'}v={a.assetClassification?.ETF||0}/><Metric k={gr?'Μετοχές':'Stocks'}v={a.assetClassification?.STOCK||0}/><Metric k={gr?'Άγνωστος τύπος':'Unknown asset'}v={a.assetClassification?.UNKNOWN||0}/><Metric k={gr?'Duplicates':'Duplicates'}v={a.duplicateRows}/></div><section className="section"><h2>{gr?'Πηγή ταξινόμησης asset':'Asset classification source'}</h2><p>{gr?'Προτεραιότητα: ξεχωριστό upload → Asset Type field του CSV → γνωστό ETF registry → UNKNOWN. Δεν γίνεται πλέον fallback σε STOCK.':'Priority: dedicated upload → CSV Asset Type field → known ETF registry → UNKNOWN. There is no longer a fallback to STOCK.'}</p><div className="chips">{Object.entries(a.assetClassification?.sources||{}).map(([k,v])=><span key={k}>{k}: {v}</span>)}</div>{a.assetClassification?.batches?.length>0&&<div className="batchAudit">{a.assetClassification.batches.map((b,i)=><div key={i}><b>{b.forcedAssetType}</b><span>{b.filename}</span><small>{b.rows} rows</small></div>)}</div>}{a.assetClassification?.unknownTickers?.length>0&&<div className="warning"><b>UNKNOWN:</b> {a.assetClassification.unknownTickers.join(', ')}</div>}</section>{a.warnings.length>0&&<section className="auditWarnings"><h3>{gr?'Σημεία προσοχής':'Warnings'}</h3>{a.warnings.map((w,i)=><div key={i}>⚠ {w}</div>)}</section>}<section className="section"><h2>{gr?'Χαρτογράφηση πεδίων':'Field mapping'}</h2><div className="auditGrid">{Object.entries(a.detected).map(([k,v])=><div className={`auditField ${v?'ok':'missing'}`}key={k}><span>{labels[k]||k}</span><b>{v||'NOT DETECTED'}</b></div>)}</div></section><section className="section"><h2>{gr?'Κάλυψη πάνω στο premium':'Premium-weighted field coverage'}</h2><div className="coverageBars">{Object.entries(a.premiumFieldCoverage).map(([k,v])=><div key={k}><span>{k}</span><div className="bar"><i style={{width:`${v}%`}}/></div><b>{v}%</b></div>)}</div></section><section className="section"><h2>{gr?'Headers που βρέθηκαν':'Detected CSV headers'}</h2><div className="chips">{a.headers.map(h=><span key={h}>{h}</span>)}</div></section></>}

function TickerPage({s,analysis,lang,mode,t,tab,setTab,quote,ai,refresh,runAI,go,watched,toggleWatch}){const gr=lang==='el';if(!analysis)return <Empty lang={lang}/>;if(!s)return <div className="empty"><b>{gr?'Το ticker δεν υπάρχει στο τρέχον CSV.':'Ticker is not present in the current CSV.'}</b><button onClick={()=>go('dashboard')}>{gr?'Επιστροφή στο dashboard':'Back to dashboard'}</button></div>;return <><div className="tickerNav"><button onClick={()=>history.back()}>← {t.back}</button><button className={`star big ${watched?'on':''}`}onClick={()=>toggleWatch(s.symbol)}>{watched?'★ Watchlist':'☆ Watchlist'}</button></div><div className="hero"><div><div className="symbol">{s.symbol} <em>{s.asset.type} · {s.asset.sector}</em></div><div className="heroBias">{dirEl(s.bias)} <span className="heroConf">{s.confidence}%</span><i className={`quality ${qualityClass(s.signalQuality)}`}>Q {s.signalQuality}</i></div>{quote?.close>0&&<div className="price">${quote.close.toFixed(2)} <small>{quote.percent_change?.toFixed?.(2)}%</small></div>}</div><div className="actions"><button onClick={()=>refresh(s)}>{t.refresh}</button><button className="aiBtn"onClick={()=>runAI(s,false)}disabled={ai?.loading}>{ai?.loading?'AI…':s.aiRecommended?t.analyze:(gr?'AI προαιρετικό':'AI optional')}</button></div></div><div className="metrics"><Metric k={t.score}v={signed(s.score)}/><Metric k={t.conf}v={`${s.confidence}%`}/><Metric k={t.coverage}v={`${s.coverage}%`}/><Metric k="Signal Quality"v={s.signalQuality}/><Metric k="Gamma"v={s.gammaContext}/><Metric k={t.legacy}v={`${s.legacy.bias} ${signed(s.legacy.score)}`}/></div><div className="tabs">{[['signals',t.signals],['plan',t.plan],['risk',t.risk]].map(([k,l])=><button className={tab===k?'active':''}onClick={()=>setTab(k)}key={k}>{l}</button>)}</div>{tab==='signals'&&<Signals s={s}mode={mode}lang={lang}ai={ai}runAI={()=>runAI(s,true)}/>} {tab==='plan'&&<TradePlan s={s}lang={lang}quote={quote}/>} {tab==='risk'&&<Risk s={s}lang={lang}ai={ai}/>} {mode==='advanced'&&<><AdvancedData s={s}/><Inspector s={s}/></>}</>}

function Empty({lang}){return <div className="empty"><b>{lang==='el'?'Ξεκίνα με το ίδιο workflow που χρησιμοποιείς ήδη.':'Start with the same workflow you already use.'}</b><p>{lang==='el'?'Κατέβασε το Options Flow CSV από Barchart και ανέβασέ το από πάνω. Το deterministic engine κάνει την επεξεργασία τοπικά στον browser.':'Download the Options Flow CSV from Barchart and upload it above. The deterministic engine processes it locally in your browser.'}</p></div>}
function Metric({k,v}){return <div className="metric"><small>{k}</small><b>{v}</b></div>}

function Signals({s,mode,lang,ai,runAI}){const gr=lang==='el',syn=ai?.synthesis,beginner=syn?.beginner?.[lang];return <div className="panel"><h3>{gr?'Τι βλέπουμε':'What we see'}</h3>{mode==='simple'?<><p className="lead">{beginner||(gr?simpleGR(s):simpleEN(s))}</p><div className="explain"><b>{gr?'Γιατί έχει σημασία':'Why this matters'}</b><p>{syn?.why?.[lang]||(gr?whyGR(s):whyEN(s))}</p></div>{syn?.supports?.[lang]?.length>0&&<BulletBox title={gr?'Τι στηρίζει το signal':'What supports the signal'}items={syn.supports[lang]}kind="support"/>}</>:<AdvancedSummary s={s}/>} {ai?.skipped&&<div className="aiSkip"><b>{gr?'Το AI δεν κλήθηκε':'AI was not called'}</b><p>{gr?'Το deterministic signal είναι κάτω από τα προτεινόμενα thresholds, ώστε να μη σπαταλάμε API calls σε αδύναμα δεδομένα. Μπορείς να το τρέξεις χειροκίνητα για έλεγχο.':'The deterministic signal is below the recommended thresholds, so we avoid spending API calls on weak evidence. You can still force a manual review.'}</p><small>{ai.reason}</small><button onClick={runAI}>{gr?'Τρέξε AI ούτως ή άλλως':'Run AI anyway'}</button></div>} {ai?.error&&<div className="error">AI: {ai.error}</div>}{ai?.errors?.length>0&&<div className="warning">{ai.errors.join(' · ')}</div>}{mode==='advanced'&&ai&&(ai.primary||ai.second)&&<AIReview ai={ai}lang={lang}/>}</div>}
const simpleGR=s=>s.bias==='BULLISH'?`Η ροή των options για ${s.symbol} γέρνει ανοδικά. Το score ${signed(s.score)} δείχνει την κατεύθυνση και την ένταση του flow, όχι βεβαιότητα ότι η τιμή θα ανέβει.`:s.bias==='BEARISH'?`Η ροή των options για ${s.symbol} γέρνει πτωτικά. Το score ${signed(s.score)} είναι σήμα αυξημένης προσοχής, όχι πρόβλεψη με βεβαιότητα.`:`Η εικόνα για ${s.symbol} είναι μικτή. Το engine δεν βρίσκει αρκετά καθαρή directional υπεροχή.`;
const simpleEN=s=>s.bias==='BULLISH'?`Options flow for ${s.symbol} leans bullish. The ${signed(s.score)} score describes direction and strength of the flow, not certainty that price will rise.`:s.bias==='BEARISH'?`Options flow for ${s.symbol} leans bearish. The ${signed(s.score)} score is a reason for added attention, not a certain prediction.`:`The picture for ${s.symbol} is mixed. The engine does not find a clean directional advantage.`;
const whyGR=s=>`Score ${signed(s.score)}, βεβαιότητα ${s.confidence}% και κάλυψη ${s.coverage}%. Η βεβαιότητα βαθμολογεί την ποιότητα των evidence, ενώ η κάλυψη δείχνει πόσο από το premium μπόρεσε να πάρει καθαρή directional ταξινόμηση. ${s.openingCoverage<30?'Η opening/closing πληροφορία είναι περιορισμένη, άρα το signal χρειάζεται περισσότερη προσοχή. ':''}${s.sectorConfirmation.label==='CONFIRMED'?`Υπάρχει επιβεβαίωση από ${s.sectorConfirmation.peers.join(', ')}.`:s.sectorConfirmation.label==='CONFLICTING'?`Τα ${s.sectorConfirmation.peers.join(', ')} δείχνουν αντίθετη εικόνα και μειώνουν την εμπιστοσύνη.`:'Δεν υπάρχει αρκετή sector/index επιβεβαίωση μέσα στο συγκεκριμένο upload.'}`;
const whyEN=s=>`Score ${signed(s.score)}, confidence ${s.confidence}% and coverage ${s.coverage}%. Confidence rates evidence quality, while coverage shows how much premium received a clean directional classification. ${s.openingCoverage<30?'Opening/closing information is limited, so the signal deserves extra caution. ':''}${s.sectorConfirmation.label==='CONFIRMED'?`The direction is confirmed by ${s.sectorConfirmation.peers.join(', ')}.`:s.sectorConfirmation.label==='CONFLICTING'?`${s.sectorConfirmation.peers.join(', ')} conflict with the signal and reduce confidence.`:'There is not enough sector/index confirmation inside this upload.'}`;
function BulletBox({title,items,kind=''}){return <div className={`bulletBox ${kind}`}><b>{title}</b><ul>{items.map((x,i)=><li key={i}>{x}</li>)}</ul></div>}
function AdvancedSummary({s}){return <div className="grid"><Metric k="Bull weighted"v={money(s.bullishWeighted)}/><Metric k="Bear weighted"v={money(s.bearishWeighted)}/><Metric k="Opening coverage"v={`${s.openingCoverage}%`}/><Metric k="Closing coverage"v={`${s.closingCoverage}%`}/><Metric k="Execution coverage"v={`${s.executionCoverage}%`}/><Metric k="Unusual premium"v={`${s.unusualShare}%`}/><Metric k="0DTE rows"v={s.zeroDTE}/><Metric k="Unknown DTE"v={s.unknownDTE}/><Metric k="Multi-leg groups"v={s.multiLegGroups}/><Metric k="Top-1 concentration"v={`${s.concentration.top1}%`}/></div>}
function AIReview({ai,lang}){const p=ai.primary,s=ai.second;return <div className="aiReview"><div><h4>Claude · Analyst</h4><p>{p?.institutionalInterpretation?.[lang]||p?.advanced?.[lang]||p?.why?.[lang]||'—'}</p>{p?.supports?.[lang]&&<ul>{p.supports[lang].slice(0,4).map((x,i)=><li key={i}>{x}</li>)}</ul>}</div><div><h4>OpenAI · Skeptic</h4><p>{s?.alternativeExplanation?.[lang]||s?.advanced?.[lang]||s?.why?.[lang]||'—'}</p>{s?.risks?.[lang]&&<ul>{s.risks[lang].slice(0,5).map((x,i)=><li key={i}>{x}</li>)}</ul>}</div></div>}

function TradePlan({s,lang,quote}){const gr=lang==='el';return <div className="panel"><h3>{gr?'Πλάνο παρακολούθησης — όχι εντολή συναλλαγής':'Monitoring plan — not a trade instruction'}</h3><p>{gr?'Χρησιμοποίησε το signal σαν σενάριο που χρειάζεται επιβεβαίωση από την τιμή. Μην βασίζεις απόφαση μόνο στο options flow.':'Use the signal as a scenario that still needs confirmation from price. Do not base a decision only on options flow.'}</p><div className="steps"><div><b>1</b>{gr?'Κατεύθυνση':'Direction'}: {s.bias} · Score {signed(s.score)}</div><div><b>2</b>{gr?'Περίμενε price confirmation. Ένα καλό flow signal χωρίς επιβεβαίωση της τιμής παραμένει υπόθεση.':'Wait for price confirmation. A strong flow signal without price confirmation remains a hypothesis.'}</div><div><b>3</b>{gr?'Έλεγξε sector/index context και μην κυνηγάς κίνηση που έχει ήδη επεκταθεί πολύ.':'Check sector/index context and avoid chasing an already extended move.'}</div><div><b>4</b>{gr?'Ακύρωσε το σενάριο αν η τιμή και το broader context κινούνται σταθερά αντίθετα.':'Invalidate the scenario if price and broader context persistently move against it.'}</div></div>{quote?.close?<p className="note">{gr?'Τελευταία τιμή Twelve Data μετά από χειροκίνητο refresh:':'Latest Twelve Data price after manual refresh:'} ${quote.close.toFixed(2)} ({quote.percent_change?.toFixed?.(2)}%)</p>:null}</div>}
function Risk({s,lang,ai}){const gr=lang==='el',risks=ai?.synthesis?.risks?.[lang];const defaults=gr?[`${100-s.coverage}% του premium δεν έχει καθαρή directional ταξινόμηση.`,s.multiLegTrades?`${s.multiLegTrades} γραμμές ανήκουν πιθανώς σε multi-leg δομές και έχουν downweight.`:'Δεν εντοπίστηκαν probable multi-leg γραμμές με τα διαθέσιμα timestamps.',s.openingCoverage<50?`Μόνο ${s.openingCoverage}% του premium έχει explicit opening classification. Δεν θεωρούμε άγνωστα trades ως BTO/STO.`:`Το explicit opening coverage είναι ${s.openingCoverage}%.`,s.concentration.top1>35?`Το μεγαλύτερο trade αντιστοιχεί σε ${s.concentration.top1}% του premium — concentration risk.`:'Δεν υπάρχει ακραία συγκέντρωση σε ένα μόνο trade.']:[`${100-s.coverage}% of premium lacks a clean directional classification.`,s.multiLegTrades?`${s.multiLegTrades} rows are likely part of multi-leg structures and are downweighted.`:'No probable multi-leg rows were detected from the available timestamps.',s.openingCoverage<50?`Only ${s.openingCoverage}% of premium has explicit opening classification. Unknown trades are not treated as known BTO/STO.`:`Explicit opening coverage is ${s.openingCoverage}%.`,s.concentration.top1>35?`The largest trade represents ${s.concentration.top1}% of premium — concentration risk.`:'There is no extreme single-trade concentration.'];return <div className="panel"><h3>{gr?'Τι μπορεί να πάει στραβά':'What can go wrong'}</h3><ul>{(risks?.length?risks:defaults).map((x,i)=><li key={i}>{x}</li>)}</ul><div className="warning">{gr?'Το confidence είναι quality score των δεδομένων — όχι πιθανότητα κέρδους. Το flow μπορεί να είναι hedge, closing activity ή μέρος σύνθετης στρατηγικής.':'Confidence is a data-quality score — not probability of profit. Flow can be hedging, closing activity or part of a complex strategy.'}</div></div>}

function AdvancedData({s}){return <section className="panel"><h3>Deterministic Evidence Summary</h3><div className="split"><div><h4>Execution</h4><Breakdown data={s.breakdown.execution}/></div><div><h4>Position effect</h4><Breakdown data={s.breakdown.position}/></div><div><h4>DTE</h4><Breakdown data={s.breakdown.dte}/></div></div><div className="qualityNote">Field coverage: side {s.dataQuality.sideCoverage}% · timestamp {s.dataQuality.timestampCoverage}% · explicit position {s.dataQuality.explicitPositionCoverage}% · OI {s.dataQuality.oiCoverage}% · volume {s.dataQuality.volumeCoverage}% · delta {s.dataQuality.deltaCoverage}%</div>{s.groupSummaries.length>0&&<><h4>Probable multi-leg groups</h4><div className="chips">{s.groupSummaries.slice(0,8).map(g=><span key={g.group}>{g.group} · {g.strategy} · {money(g.premium)}</span>)}</div></>}</section>}
function Breakdown({data}){return <div className="miniBreak">{Object.entries(data||{}).map(([k,v])=><div key={k}><span>{k}</span><b>{v.share}%</b><small>{money(v.premium)}</small></div>)}</div>}
function Inspector({s}){return <div className="panel inspector"><h3>Classification Inspector</h3><p className="inspectorNote">Closing trades can lean directionally, but are heavily downweighted because they reduce existing exposure rather than create a new opening position. UNKNOWN position effect is never silently promoted to BTO/STO.</p><div className="table"><table><thead><tr><th>Batch</th><th>Row</th><th>Contract</th><th>Side</th><th>Tx</th><th>Position</th><th>Intent</th><th>Direction</th><th>Premium</th><th>Weight</th><th>Conv.</th><th>Vol/OI</th><th>Strategy</th><th>Time</th></tr></thead><tbody>{s.trades.slice(0,120).map(t=><tr key={t.id}><td>{t.batchKind}</td><td>{t.row}</td><td>{t.symbol} {t.expiry||'?'} {t.strike}{t.type[0]}</td><td>{t.side}</td><td>{t.tx}</td><td>{t.positionEffect}</td><td>{t.intent}</td><td>{t.direction}</td><td>{money(t.premium)}</td><td>{t.effectWeight.toFixed(2)}</td><td>{Math.round(t.conviction*100)}%</td><td>{t.oi?(t.volume/t.oi).toFixed(2):'—'}</td><td>{t.group?`${t.group} ${t.strategy}`:'SINGLE'}</td><td>{t.time||'—'}</td></tr>)}</tbody></table></div></div>}

createRoot(document.getElementById('root')).render(<App/>);
